test("drops the lowest of four homework scores and applies the category weights", function () {
  var actual = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 75, examScore: 60, final: 70.5, display: "70.5", droppedHomework: 70 });
});

test("averages three homework scores and does not drop any", function () {
  var actual = code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 80, quizAverage: 75, examScore: 60, final: 68.5, display: "68.5", droppedHomework: null });
});

test("drops the first of five homework scores", function () {
  var actual = code.finalGrade({ homework: [50, 90, 80, 70, 60], quizzes: [40], exam: [80] });
  assert.deepEqual(actual, { homeworkAverage: 75, quizAverage: 40, examScore: 80, final: 67.0, display: "67.0", droppedHomework: 50 });
});

test("drops the last homework score when it is the lowest", function () {
  var actual = code.finalGrade({ homework: [90, 80, 70, 60], quizzes: [50], exam: [50] });
  assert.deepEqual(actual, { homeworkAverage: 80, quizAverage: 50, examScore: 50, final: 56.0, display: "56.0", droppedHomework: 60 });
});

test("drops only one of two tied lowest homework scores", function () {
  var actual = code.finalGrade({ homework: [40, 80, 40, 100], quizzes: [90], exam: [90] });
  assert.deepEqual(actual, { homeworkAverage: 220 / 3, quizAverage: 90, examScore: 90, final: 86.7, display: "86.7", droppedHomework: 40 });
});

test("averages four quiz scores and does not drop any quiz", function () {
  var actual = code.finalGrade({ homework: [100], quizzes: [10, 20, 30, 100], exam: [100] });
  assert.deepEqual(actual, { homeworkAverage: 100, quizAverage: 40, examScore: 100, final: 82.0, display: "82.0", droppedHomework: null });
});

test("counts empty quizzes as zero and keeps the trailing decimal", function () {
  var actual = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 0, examScore: 60, final: 48.0, display: "48.0", droppedHomework: 70 });
});

test("counts empty homework as zero", function () {
  var actual = code.finalGrade({ homework: [], quizzes: [80, 60], exam: [50] });
  assert.deepEqual(actual, { homeworkAverage: 0, quizAverage: 70, examScore: 50, final: 46.0, display: "46.0", droppedHomework: null });
});

test("counts an empty exam as zero", function () {
  var actual = code.finalGrade({ homework: [100], quizzes: [100], exam: [] });
  assert.deepEqual(actual, { homeworkAverage: 100, quizAverage: 100, examScore: 0, final: 50.0, display: "50.0", droppedHomework: null });
});

test("counts every empty category as zero", function () {
  var actual = code.finalGrade({ homework: [], quizzes: [], exam: [] });
  assert.deepEqual(actual, { homeworkAverage: 0, quizAverage: 0, examScore: 0, final: 0.0, display: "0.0", droppedHomework: null });
});

test("drops a zero homework score and keeps a zero quiz score in the average", function () {
  var actual = code.finalGrade({ homework: [0, 100, 90, 80], quizzes: [0, 60], exam: [40] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 30, examScore: 40, final: 47.0, display: "47.0", droppedHomework: 0 });
});

test("does not drop a single homework score", function () {
  var actual = code.finalGrade({ homework: [88], quizzes: [77], exam: [66] });
  assert.deepEqual(actual, { homeworkAverage: 88, quizAverage: 77, examScore: 66, final: 73.7, display: "73.7", droppedHomework: null });
});

test("rounds a non-half final of 75.983 to the nearer value 76.0", function () {
  var actual = code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] });
  assert.deepEqual(actual, { homeworkAverage: 245 / 3, quizAverage: 70.5, examScore: 77, final: 76.0, display: "76.0", droppedHomework: null });
});

test("rounds a non-half final of 75.916 down to the nearer value 75.9", function () {
  var actual = code.finalGrade({ homework: [80, 80, 84], quizzes: [70, 71], exam: [77] });
  assert.deepEqual(actual, { homeworkAverage: 244 / 3, quizAverage: 70.5, examScore: 77, final: 75.9, display: "75.9", droppedHomework: null });
});

test("throws unknown field when the input has a bonus field", function () {
  assert.throws(function () {
    code.finalGrade({ homework: [90], quizzes: [80], exam: [70], bonus: 5 });
  }, /^unknown field: bonus$/);
});

test("averages two homework scores and does not drop any", function () {
  var actual = code.finalGrade({ homework: [30, 90], quizzes: [40, 50], exam: [70] });
  assert.deepEqual(actual, { homeworkAverage: 60, quizAverage: 45, examScore: 70, final: 60.5, display: "60.5", droppedHomework: null });
});
